using System;
using System.Collections.Generic;
using System.Text;
using System.Text.RegularExpressions;
using System.Diagnostics;
using System.Threading.Tasks;
using System.IO;
public class Server {public bool IsLocal{get;set;}public string Name{get;set;}public string Host{get;set;}public string User{get;set;}public int Port{get;set;}public string KeyPath{get;set;}public Server(){Name="";Host="";User="";Port=22;KeyPath="";}public override string ToString(){return Name+" / "+Host;}public Server Copy(){return new Server{IsLocal=IsLocal,Name=Name,Host=Host,User=User,Port=Port,KeyPath=KeyPath};}}
public class Settings {public TerminalPreferences Terminal{get;set;}public string[] HistoryModuleOrder{get;set;}public double MiniLeft{get;set;}public double MiniTop{get;set;}public double MiniWidth{get;set;}public double MiniHeight{get;set;}public bool MiniPinned{get;set;}public int RetentionDays{get;set;}public int ArchiveLimitMB{get;set;}public List<Server> Servers{get;set;}public string ThemeName{get;set;}public string SelectedView{get;set;}public int Interval{get;set;}public bool CloseToTray{get;set;}public string SelectedName{get;set;}public Settings(){Terminal=new TerminalPreferences();HistoryModuleOrder=new[]{"curve","process","hardware"};MiniLeft=double.NaN;MiniTop=double.NaN;MiniWidth=360;MiniHeight=480;MiniPinned=true;Servers=new List<Server>();RetentionDays=30;ArchiveLimitMB=1024;ThemeName="graphite";SelectedView="CPU";Interval=5;CloseToTray=true;SelectedName="aq-server";}public Settings Copy(){var s=new Settings{Terminal=(Terminal??new TerminalPreferences()).Copy(),HistoryModuleOrder=HistoryModuleOrder==null?null:(string[])HistoryModuleOrder.Clone(),MiniLeft=MiniLeft,MiniTop=MiniTop,MiniWidth=MiniWidth,MiniHeight=MiniHeight,MiniPinned=MiniPinned,RetentionDays=RetentionDays,ArchiveLimitMB=ArchiveLimitMB,ThemeName=ThemeName,SelectedView=SelectedView,Interval=Interval,CloseToTray=CloseToTray,SelectedName=SelectedName};foreach(var x in Servers)s.Servers.Add(x.Copy());return s;}}
public class Gpu {public string Index,Name,Util,Used,Total,Temp,Fan,Power,Cap,Uuid,PowerMax,CapSource;}
public class GpuProcess {public string Gpu,Pid,Type,Name,Memory,User="—",SharedMemory,MemorySource;}
public class CpuCore {public int Index;public double Util;}
public class Metrics {public HardwareInfo Hardware;public List<CpuCore> CpuCores=new List<CpuCore>();public List<Gpu> Gpus=new List<Gpu>();public List<GpuProcess> Processes=new List<GpuProcess>();public string Cpu="—",Cores="—",Mem="—",Disk="—",Raw="",Error="";}
public static class Remote {
 static string Q(string s){return "\""+s.Replace("\"","\\\"")+"\"";}
 public static Metrics Collect(Server s){if(s.IsLocal)return Local.Collect();var m=new Metrics();if(!Regex.IsMatch(s.Host??"",@"^[a-zA-Z0-9._:-]+$")||!Regex.IsMatch(s.User??"",@"^[a-zA-Z0-9._-]*$")||s.Port<1||s.Port>65535){m.Error="服务器地址、用户名或端口无效";return m;}
 // Only fixed diagnostic commands are sent; configuration values become SSH arguments.
 const string script="printf 'AQCPU\\n'; awk 'BEGIN{while((getline line < \"/proc/stat\")>0){split(line,a);if(a[1] ~ /^cpu[0-9]*$/){for(i=2;i<=9;i++) t[a[1]]+=a[i];idle[a[1]]=a[5]+a[6]}}close(\"/proc/stat\");system(\"sleep 0.5\");while((getline line < \"/proc/stat\")>0){split(line,a);if(a[1] ~ /^cpu[0-9]*$/){total=0;for(i=2;i<=9;i++)total+=a[i];d=total-t[a[1]];busy=d>0?100*(d-(a[5]+a[6]-idle[a[1]]))/d:0;printf \"%s,%.1f\\n\",a[1],busy}}}'; printf 'AQCORES\\n'; nproc 2>/dev/null; printf 'AQMEM\\n'; LC_ALL=C free -m 2>/dev/null | awk '/^Mem:/ {print $3\" / \"$2\" MiB\"}'; printf 'AQDISK\\n'; df -h / 2>/dev/null | awk 'NR==2{print $5\" used / \"$4\" free\"}'; printf 'AQGPU\\n'; if command -v nvidia-smi >/dev/null 2>&1; then nvidia-smi --query-gpu=index,name,utilization.gpu,memory.used,memory.total,temperature.gpu,fan.speed,power.draw,power.limit,uuid,power.max_limit --format=csv,noheader,nounits 2>/dev/null; fi; printf 'AQPROC\\n'; if command -v nvidia-smi >/dev/null 2>&1; then nvidia-smi --query-compute-apps=gpu_uuid,pid,process_name,used_gpu_memory --format=csv,noheader,nounits 2>/dev/null; fi; printf 'AQUSERS\\n'; ps -eo pid=,user:64= 2>/dev/null; printf 'AQEND\\n'";
 var args="-n -o BatchMode=yes -o ConnectTimeout=7 -o StrictHostKeyChecking=accept-new -p "+s.Port+" ";if(!string.IsNullOrWhiteSpace(s.KeyPath))args+="-i "+Q(Environment.ExpandEnvironmentVariables(s.KeyPath))+" ";var dest=string.IsNullOrWhiteSpace(s.User)?s.Host:s.User+"@"+s.Host;args+="-- "+Q(dest)+" "+Q(script);
 var p=new Process{StartInfo=new ProcessStartInfo("ssh.exe",args){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8}};try{p.Start();var stdout=p.StandardOutput.ReadToEndAsync();var stderr=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(14000)){try{p.Kill();}catch{}m.Error="SSH 连接超时";return m;}m.Raw=stdout.Result;string err=stderr.Result;if(p.ExitCode!=0){m.Error=err.Trim();if(m.Error.Length>220)m.Error=m.Error.Substring(0,220);if(m.Error.Length==0)m.Error="SSH 连接失败 ("+p.ExitCode+")";return m;}}
 catch(Exception ex){m.Error=ex.Message;return m;}finally{p.Dispose();}
 var owners=new Dictionary<string,string>();string section="";foreach(var raw in m.Raw.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries)){string line=raw.Trim();if(Regex.IsMatch(line,@"^AQ(CPU|CORES|MEM|DISK|GPU|PROC|USERS|END)$")){section=line;continue;}if(section=="AQUSERS"){var owner=Regex.Match(line,@"^(\d+)\s+(\S+)$");if(owner.Success)owners[owner.Groups[1].Value]=owner.Groups[2].Value;}if(section=="AQCPU"){var a=line.Split(',');if(a.Length==2){if(a[0]=="cpu")m.Cpu=a[1]+"%";else{int index;double usage;if(int.TryParse(a[0].Substring(3),out index)&&double.TryParse(a[1],System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out usage))m.CpuCores.Add(new CpuCore{Index=index,Util=Math.Max(0,Math.Min(100,usage))});}}}if(section=="AQCORES")m.Cores=line;if(section=="AQMEM")m.Mem=line;if(section=="AQDISK")m.Disk=line;if(section=="AQGPU"){var a=line.Split(',');if(a.Length>=9)m.Gpus.Add(new Gpu{Index=a[0].Trim(),Name=a[1].Trim(),Util=a[2].Trim(),Used=a[3].Trim(),Total=a[4].Trim(),Temp=a[5].Trim(),Fan=a[6].Trim(),Power=a[7].Trim(),Cap=a[8].Trim(),Uuid=a.Length>=10?a[9].Trim():"",PowerMax=a.Length>=11?a[10].Trim():null});}if(section=="AQPROC"){var a=line.Split(',');if(a.Length>=4){string uuid=a[0].Trim();var gpu=m.Gpus.Find(x=>x.Uuid==uuid);m.Processes.Add(new GpuProcess{Gpu=gpu==null?"?":gpu.Index,Pid=a[1].Trim(),Type="C",Name=string.Join(",",a,2,a.Length-3).Trim(),Memory=a[a.Length-1].Trim()+" MiB"});}}}foreach(var process in m.Processes){string owner;if(owners.TryGetValue(process.Pid,out owner))process.User=owner;}m.Hardware=HardwareInventory.Get(s);return m;}
}
